unity command --format json 2>/dev/null > /tmp/unity_commands.json; python3 -c "
import json
d = json.load(open('/tmp/unity_commands.json'))
for c in d['data']['commands']:
    if 'gameobject' in c['name'].lower() or 'transform' in c['name'].lower():
        print(c['name'], '-', c['description'])
        for p in c['parameters']:
            print('   ', p['name'], p['type'], 'required' if p['required'] else 'optional', p.get('defaultValue'))
"

